// Les Amériques (the update « pays-ameriques »; the rest of Canada with « pays-canada »): Toronto, Ottawa,
// Québec, Vancouver, Calgary, Edmonton, Winnipeg and Halifax beside Montréal; Latin America and the
// Caribbean, São Paulo, Rio, Salvador de Bahia and Brasília, Mexico and Cancún, Port-au-Prince and
// Cap-Haïtien, La Havane, Bogota and Carthagène, Buenos Aires in depth (two or three quarters each), the
// capital or great city of every other country (one centre each). Their centres, city halls, airports
// (Air Lagune flies there, game/ameriques.go) and famous places are positioned from OpenStreetMap
// (Nominatim, 26 November 2026; those placed by hand say so); the restaurants, clubs, hotels, barbers and
// shops are the game's. Generated from that lookup, the streets and the buildings
// coming from OpenStreetMap like everywhere.
//
// The roads (SameLand): Canada, the United States, Mexico and Central America are one land (the road goes
// down to Panama); South America another (the Darién Gap: no road between Panama and Colombia); Haïti and
// the Dominican Republic share Hispaniola; every other island (Cuba, Jamaïque, Porto Rico, Trinité, la
// Guadeloupe, la Martinique) is reached by plane only (City.Island). Over there, nothing Ivorian in the
// streets (west.go InAmerica: every land of the Americas).

// AmeriquesKey: the update that opens Latin America and the Caribbean.
const AmeriquesKey = game.AmeriquesKey

// (This file's init runs before the others of the package, which read Cities: the files go in name order.)
func init() {
	for _, k := range ameriquesCountries {
		Countries[k.ID] = k
	}
	Cities = append(Cities, ameriques...)
}

// AmericanLand: whether a land is one of the Americas' (North and Central America, South America, Hispaniola).
func AmericanLand(land string) bool { return strings.HasPrefix(land, "amerique") }

// AmeriquesCommunes: every commune of the countries « pays-ameriques » opens (its update hides them).
func AmeriquesCommunes() []string {
	var out []string
	for _, k := range ameriquesCountries {
		out = append(out, CountryCommunes(k.ID)...)
	}
	return out
}

